@startuml

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + name : string
}

class Runner {
  + runnerId : int
  + horseName : string
}

class Jockey {
  + name : string
}

class Bet {
  + amount : double
  + odds : double
}

Bettor "1" -- "*" Bet
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

